create or replace function public.forbid_audit_log_mutation()
returns trigger
language plpgsql
as $$
begin
  raise exception 'audit_log is append-only';
end;
$$;

create or replace function public.tenants_phone_only_update()
returns trigger
language plpgsql
as $$
begin
  if new.id is distinct from old.id
    or new.org_id is distinct from old.org_id
    or new.user_id is distinct from old.user_id
    or new.full_name is distinct from old.full_name
    or new.email is distinct from old.email
    or new.created_at is distinct from old.created_at
  then
    raise exception 'tenants may only update phone';
  end if;
  new.updated_at = now();
  return new;
end;
$$;

create or replace function public.current_org_ids()
returns setof uuid
language sql
stable
security definer
set search_path = public
as $$
  select org_id
  from public.memberships
  where user_id = auth.uid()
  union
  select org_id
  from public.tenants
  where user_id = auth.uid();
$$;

create or replace function public.current_membership_role()
returns public.membership_role
language sql
stable
security definer
set search_path = public
as $$
  select role
  from public.memberships
  where user_id = auth.uid()
  limit 1;
$$;

create or replace function public.is_manager()
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1
    from public.memberships
    where user_id = auth.uid()
      and role = 'manager'
  );
$$;

create or replace function public.is_staff_or_manager()
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1
    from public.memberships
    where user_id = auth.uid()
  );
$$;

create or replace function public.is_tenant()
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1
    from public.tenants
    where user_id = auth.uid()
  );
$$;

create or replace function public.tenant_lease_ids()
returns setof uuid
language sql
stable
security definer
set search_path = public
as $$
  select l.id
  from public.leases l
  join public.tenants t on t.id = l.tenant_id
  where t.user_id = auth.uid();
$$;

create trigger audit_log_append_only
before update or delete on public.audit_log
for each row execute function public.forbid_audit_log_mutation();

create trigger tenants_phone_only_update
before update on public.tenants
for each row execute function public.tenants_phone_only_update();

