/** Format integer sen as `RM 1,234.56` for display. */
export function formatRinggit(sen: number): string {
  const ringgit = sen / 100;
  return `RM ${ringgit.toLocaleString("en-MY", {
    minimumFractionDigits: 2,
    maximumFractionDigits: 2,
  })}`;
