  const overlap = await createLeaseRoute(
    authRequest("http://localhost/api/leases", northwindManagerToken, {
      method: "POST",
      body: JSON.stringify({
        ...payload,
        startDate: "2028-06-01",
        endDate: "2028-12-31",
      }),
    }),
  );
