"use client";

import { useMemo, useState } from "react";
import { useRouter } from "next/navigation";
import { toast } from "sonner";
import {
  generateSchedule,
  parseRinggitToSen,
  type ScheduledInvoice,
} from "@/lib/billing";
import { formatDisplayDate } from "@/lib/dates";
import { formatRinggit } from "@/lib/money";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";

export function CreateLeaseForm({
  units,
  tenants,
}: {
  units: { id: string; name: string }[];
  tenants: { id: string; fullName: string; email: string }[];
}) {
  const router = useRouter();
  const [unitId, setUnitId] = useState(units[0]?.id ?? "");
  const [tenantId, setTenantId] = useState(tenants[0]?.id ?? "");
  const [startDate, setStartDate] = useState("2026-01-31");
  const [endDate, setEndDate] = useState("2026-07-15");
  const [rentInput, setRentInput] = useState("1,500.00");
  const [depositInput, setDepositInput] = useState("3,000.00");
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const preview = useMemo(() => {
    try {
      const monthlyRentSen = parseRinggitToSen(rentInput);
      const depositSen = parseRinggitToSen(depositInput);
      if (depositSen < 0) {
        return { schedule: [] as ScheduledInvoice[], error: "Deposit cannot be negative." };
      }
      const schedule = generateSchedule({
        startDate,
        endDate,
        monthlyRentSen,
        depositSen,
      });
      return { schedule, error: null as string | null };
    } catch (err) {
      return {
        schedule: [] as ScheduledInvoice[],
        error: err instanceof Error ? err.message : "Invalid schedule inputs",
      };
    }
  }, [startDate, endDate, rentInput, depositInput]);

  async function onSubmit(event: React.FormEvent) {
    event.preventDefault();
    setError(null);
    setLoading(true);
    try {
      if (!unitId || !tenantId) {
        throw new Error("Choose a unit and tenant.");
      }
      const monthlyRentSen = parseRinggitToSen(rentInput);
      const depositSen = parseRinggitToSen(depositInput);
      // Validate schedule before submit (same rules as the API).
      generateSchedule({
        startDate,
        endDate,
        monthlyRentSen,
        depositSen,
      });

      const response = await fetch("/api/leases", {
        method: "POST",
        headers: { "content-type": "application/json" },
        body: JSON.stringify({
          unitId,
          tenantId,
          startDate,
          endDate,
          monthlyRentSen,
          depositSen,
        }),
      });
      const body = (await response.json()) as { error?: string; id?: string };
      if (!response.ok) {
        if (response.status === 409) {
          throw new Error(
            body.error ??
              "This lease overlaps another lease on the same unit.",
          );
        }
        throw new Error(body.error ?? "Could not create lease");
      }
      toast.success("Lease created.");
      router.push(`/leases/${body.id}`);
      router.refresh();
    } catch (err) {
      const message =
        err instanceof Error ? err.message : "Could not create lease";
      setError(message);
      toast.error(message);
    } finally {
      setLoading(false);
    }
  }

  return (
