          </p>
        </div>
        {error ? <p className="text-sm text-destructive">{error}</p> : null}
        {units.length === 0 || tenants.length === 0 ? (
          <p className="text-sm text-muted-foreground">
            Add a unit and tenant in this organization before creating a lease.
          </p>
