          </div>
          <div className="space-y-2">
            <Label htmlFor="deposit">Deposit (RM)</Label>
            <Input
              id="deposit"
              value={depositInput}
              onChange={(event) => setDepositInput(event.target.value)}
              placeholder="0 or 3,000.00"
              required
            />
          </div>
        </div>
        <Button
          type="submit"
          disabled={loading || units.length === 0 || tenants.length === 0}
