          {loading ? "Creating…" : "Create lease"}
        </Button>
      </form>

      <div className="space-y-3 rounded-xl border p-4">
        <div>
          <h2 className="text-lg font-medium">Schedule preview</h2>
          <p className="text-sm text-muted-foreground">
            Live preview from generateSchedule.
          </p>
        </div>
        {preview.error ? (
          <p className="text-sm text-muted-foreground">{preview.error}</p>
        ) : preview.schedule.length === 0 ? (
          <p className="text-sm text-muted-foreground">No invoices yet.</p>
        ) : (
          <Table>
            <TableHeader>
              <TableRow>
                <TableHead>Kind</TableHead>
                <TableHead>Period</TableHead>
                <TableHead>Due</TableHead>
                <TableHead className="text-right">Amount</TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {preview.schedule.map((row, index) => (
                <TableRow
                  key={`${row.kind}-${row.periodIndex ?? "d"}-${index}`}
                >
                  <TableCell className="capitalize">
                    {row.kind}
                    {row.periodIndex !== null ? ` #${row.periodIndex}` : ""}
                  </TableCell>
                  <TableCell>
                    {row.periodStart && row.periodEnd
                      ? `${formatDisplayDate(row.periodStart)} – ${formatDisplayDate(row.periodEnd)}`
                      : "—"}
                  </TableCell>
                  <TableCell>{formatDisplayDate(row.dueDate)}</TableCell>
                  <TableCell className="text-right">
                    {formatRinggit(row.amountSen)}
                  </TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
        )}
      </div>
    </div>
  );
}

