"use client";

import { useEffect } from "react";
import { useRouter } from "next/navigation";
import { createBrowserSupabaseClient } from "@/lib/supabase/browser";

/**
 * Refresh the tenant portal when payments/invoices/allocations change for
 * the tenant's leases. Subscribes with the user JWT; RLS still applies.
 */
export function PortalRealtime({ leaseIds }: { leaseIds: string[] }) {
  const router = useRouter();

  useEffect(() => {
    if (leaseIds.length === 0) return;

    const supabase = createBrowserSupabaseClient();
    const filter = `lease_id=in.(${leaseIds.join(",")})`;
    const channel = supabase
      .channel(`portal-leases-${leaseIds.join("-").slice(0, 64)}`)
      .on(
        "postgres_changes",
        {
          event: "*",
          schema: "public",
          table: "payments",
          filter,
        },
        () => {
          router.refresh();
        },
      )
      .on(
        "postgres_changes",
        {
          event: "*",
          schema: "public",
          table: "invoices",
          filter,
        },
        () => {
          router.refresh();
        },
      )
      .on(
        "postgres_changes",
        {
          event: "*",
          schema: "public",
          table: "payment_allocations",
        },
        () => {
          // Allocations are scoped by RLS to the tenant's leases.
          router.refresh();
        },
      )
      .subscribe();

    return () => {
      void supabase.removeChannel(channel);
    };
  }, [leaseIds, router]);

  return null;
}

"use client";

import { useRouter, useSearchParams } from "next/navigation";
import { useState, useTransition } from "react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";

export function LeasesSearch({ initialQ }: { initialQ: string }) {
  const router = useRouter();
  const searchParams = useSearchParams();
  const [q, setQ] = useState(initialQ);
  const [pending, startTransition] = useTransition();

  function apply(nextQ: string, page = 1) {
    const params = new URLSearchParams(searchParams.toString());
    const trimmed = nextQ.trim();
    if (trimmed) params.set("q", trimmed);
    else params.delete("q");
    if (page > 1) params.set("page", String(page));
    else params.delete("page");
    const query = params.toString();
    startTransition(() => {
      router.push(query ? `/leases?${query}` : "/leases");
    });
  }

  return (
    <form
      className="flex flex-col gap-3 sm:flex-row sm:items-end"
      onSubmit={(event) => {
        event.preventDefault();
        apply(q, 1);
      }}
    >
      <div className="space-y-2 flex-1">
        <Label htmlFor="lease-search">Search unit or tenant</Label>
        <Input
          id="lease-search"
          value={q}
          onChange={(event) => setQ(event.target.value)}
          placeholder="A-12-3 or Aisyah"
        />
      </div>
      <Button type="submit" disabled={pending}>
        {pending ? "Searching…" : "Search"}
      </Button>
    </form>
  );
}

import { Suspense } from "react";
import Link from "next/link";
import { connection } from "next/server";
import { redirect } from "next/navigation";
import { requirePageActor } from "@/lib/auth";
import { listOrgLeases } from "@/lib/dashboard";
import { formatDisplayDate } from "@/lib/dates";
import { formatRinggit } from "@/lib/money";
import { AppShell } from "@/components/app-shell";
import { LeasesSearch } from "@/components/leases-search";
import { Button } from "@/components/ui/button";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";

export default function LeasesPage({
  searchParams,
}: {
  searchParams: Promise<{ q?: string; page?: string }>;
}) {
  return (
    <Suspense
      fallback={
        <main className="mx-auto w-full max-w-6xl px-6 py-8 text-muted-foreground">
          Loading leases…
        </main>
      }
    >
      <LeasesContent searchParams={searchParams} />
    </Suspense>
  );
}

async function LeasesContent({
  searchParams,
}: {
  searchParams: Promise<{ q?: string; page?: string }>;
}) {
  await connection();
  let actor;
  try {
    actor = await requirePageActor();
  } catch {
    redirect("/login");
  }
  if (actor.kind !== "membership") {
    redirect("/portal");
  }

  const params = await searchParams;
  const q = typeof params.q === "string" ? params.q : "";
  const pageRaw = Number.parseInt(params.page ?? "1", 10);
  const page = Number.isFinite(pageRaw) && pageRaw > 0 ? pageRaw : 1;

  const result = await listOrgLeases(actor, { q, page, pageSize: 10 });
  const isManager = actor.role === "manager";

  function hrefFor(nextPage: number) {
    const sp = new URLSearchParams();
    if (result.q) sp.set("q", result.q);
    if (nextPage > 1) sp.set("page", String(nextPage));
    const query = sp.toString();
    return query ? `/leases?${query}` : "/leases";
  }

  return (
    <AppShell actor={actor}>
      <div className="space-y-6">
        <div className="flex flex-col gap-4 sm:flex-row sm:items-end sm:justify-between">
          <div>
            <h1 className="text-2xl font-semibold tracking-tight">Leases</h1>
            <p className="text-muted-foreground">
              Search and page through leases in your organization.
            </p>
          </div>
          {isManager ? (
            <Button asChild>
              <Link href="/leases/new">Create lease</Link>
            </Button>
          ) : null}
        </div>

        <LeasesSearch initialQ={result.q} />

        {result.leases.length === 0 ? (
          <p className="text-sm text-muted-foreground">
            {result.q
              ? `No leases match “${result.q}”.`
              : "No leases yet."}
          </p>
        ) : (
          <div className="rounded-xl border">
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead>Unit</TableHead>
                  <TableHead>Tenant</TableHead>
                  <TableHead>Period</TableHead>
                  <TableHead className="text-right">Rent</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {result.leases.map((lease) => (
                  <TableRow key={lease.id}>
                    <TableCell>
                      <Link
                        href={`/leases/${lease.id}`}
                        className="font-medium underline-offset-4 hover:underline"
                      >
                        {lease.unitName}
                      </Link>
                    </TableCell>
                    <TableCell>{lease.tenantName}</TableCell>
                    <TableCell>
                      {formatDisplayDate(lease.startDate)} –{" "}
                      {formatDisplayDate(lease.endDate)}
                    </TableCell>
                    <TableCell className="text-right">
                      {formatRinggit(lease.monthlyRentSen)}
                    </TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          </div>
        )}

        <div className="flex flex-wrap items-center justify-between gap-3 text-sm text-muted-foreground">
          <p>
            {result.total === 0
              ? "0 results"
              : `Page ${result.page} of ${result.totalPages} · ${result.total} lease${result.total === 1 ? "" : "s"}`}
          </p>
          <div className="flex gap-2">
            {result.page > 1 ? (
              <Link
                href={hrefFor(result.page - 1)}
                className="underline-offset-4 hover:underline"
              >
                Previous
              </Link>
            ) : null}
            {result.page < result.totalPages ? (
              <Link
                href={hrefFor(result.page + 1)}
                className="underline-offset-4 hover:underline"
              >
                Next
              </Link>
            ) : null}
          </div>
        </div>
      </div>
    </AppShell>
  );
}

